#include <stdio.h>
#include <stdlib.h>
void find_range(const int *values, int n, int *min, int *max) {
  *min = values[0]; *max = values[0];
  for (int i = 1; i < n; i++) {
    if (values[i] < *min) *min = values[i];
    if (values[i] > *max) *max = values[i];
  }
}
int main(void) {
  int n;
  if (scanf("%d", &n) != 1 || n < 1 || n > 8) return 1;
  int *values = malloc((size_t)n * sizeof *values);
  if (!values) return 1;
  for (int i = 0; i < n; i++) if (scanf("%d", &values[i]) != 1) { free(values); return 1; }
  int min, max;
  find_range(values, n, &min, &max);
  printf("min=%d,max=%d\n", min, max);
  free(values);
  return 0;
