#include <stdio.h>
#include <stdlib.h>
void reverse(int *values, int n) {
  int *left = values, *right = values + n - 1;
  while (left < right) {
    int temporary = *left; *left = *right; *right = temporary;
    left++; right--;
  }
}
int main(void) {
  int n;
  if (scanf("%d", &n) != 1 || n < 1 || n > 8) return 1;
  int *values = malloc((size_t)n * sizeof *values);
  if (!values) return 1;
  for (int i = 0; i < n; i++) if (scanf("%d", &values[i]) != 1) { free(values); return 1; }
  reverse(values, n);
  for (int i = 0; i < n; i++) printf("%d%c", values[i], i + 1 == n ? '\n' : ' ');
  free(values);
  return 0;
}
